INSERT INTO courses (id, code, name, `desc`) VALUES
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000100'), 'CS100', 'Web Development Basics', 'พื้นฐานเทคโนโลยีเว็บ สถาปัตยกรรม Client-Server HTML, CSS, JavaScript และ DOM'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000101'), 'CS101', 'Discrete Mathematics', 'คณิตศาสตร์สำหรับวิทยาการคอมพิวเตอร์ ตรรกศาสตร์ เซต การพิสูจน์ ความสัมพันธ์ และกราฟ'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000102'), 'CS102', 'Programming Fundamentals', 'รายวิชาแนะนำพื้นฐานการเขียนโปรแกรม ตัวแปร นิพจน์ คำสั่งควบคุมเงื่อนไข วนลูป และฟังก์ชัน'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000111'), 'CS111', 'Object-Oriented Programming', 'การออกแบบและเขียนโปรแกรมเชิงวัตถุ คลาส อ็อบเจกต์ การสืบทอด และโพลีมอร์ฟิซึม');
INSERT INTO prerequisites (id, course_id, prerequisite_id, timestamp) VALUES
  (UUID_TO_BIN(UUID()), UUID_TO_BIN('c0000000-0000-0000-0000-000000000111'), UUID_TO_BIN('c0000000-0000-0000-0000-000000000102'), NOW());
INSERT INTO topics (id, name, `desc`) VALUES
  (UUID_TO_BIN('70000000-0000-0000-0100-000000000001'), 'Web Component', 'Internet vs WWW, Client-Server, URL, HTTP Request/Response'),
  (UUID_TO_BIN('70000000-0000-0000-0100-000000000002'), 'HTML & CSS พื้นฐาน', 'โครงสร้างและแท็ก HTML, CSS selector/property, visual hierarchy, การใช้ VS Code'),
  (UUID_TO_BIN('70000000-0000-0000-0100-000000000003'), 'Git & GitHub', 'init/add/commit, clone/push/pull, branch, merge conflict, GitHub Pages'),
  (UUID_TO_BIN('70000000-0000-0000-0100-000000000004'), 'CSS ขั้นกลาง & Bootstrap', 'box model, position, float, media query, Bootstrap grid/flex/components'),
  (UUID_TO_BIN('70000000-0000-0000-0100-000000000005'), 'HTML Forms', 'form controls, validation, GET vs POST'),
  (UUID_TO_BIN('70000000-0000-0000-0100-000000000006'), 'Dynamic Web', 'server-side (PHP) vs client-side (JavaScript/DOM), deploy บน AWS EC2, localStorage / ไฟล์ JSON'),
  (UUID_TO_BIN('70000000-0000-0000-0101-000000000001'), 'Formal Logic', 'Propositions, logical connectives, truth tables, logical equivalence, conditional statements'),
  (UUID_TO_BIN('70000000-0000-0000-0101-000000000002'), 'Predicate Logic', 'Predicates, quantifiers, nested quantifiers, derivation rules, proof sequences'),
  (UUID_TO_BIN('70000000-0000-0000-0101-000000000003'), 'Methods of Proof', 'Counterexample, direct proof, proof by contraposition, proof by contradiction'),
  (UUID_TO_BIN('70000000-0000-0000-0101-000000000004'), 'Graphs', 'Vertices และ edges, terminologies, modeling relationships using graphs'),
  (UUID_TO_BIN('70000000-0000-0000-0101-000000000005'), 'Sets, Functions, and Relations', 'Sets, functions (injection/surjection/bijection), relations, modulo arithmetic'),
  (UUID_TO_BIN('70000000-0000-0000-0101-000000000006'), 'Recursive Thinking', 'Recurrence relations, recursive definitions, proof by induction'),
  (UUID_TO_BIN('70000000-0000-0000-0101-000000000007'), 'Quantitative Thinking', 'Counting techniques, pigeonhole principle, permutations, combinations'),
  (UUID_TO_BIN('70000000-0000-0000-0102-000000000001'), 'Computer Science Fundamentals', 'โปรแกรมคืออะไร, ภาษา C, Compiler, Source Code และการทำงานของโปรแกรม'),
  (UUID_TO_BIN('70000000-0000-0000-0102-000000000002'), 'Algorithm Design', 'Algorithm, Pseudocode, Flowchart, การวิเคราะห์ปัญหา และการเรียงลำดับขั้นตอน'),
  (UUID_TO_BIN('70000000-0000-0000-0102-000000000003'), 'Structured Programming', 'โครงสร้างโปรแกรม C, main(), การแบ่งโปรแกรมเป็นส่วน ๆ และการทำงานตามลำดับ'),
  (UUID_TO_BIN('70000000-0000-0000-0102-000000000004'), 'Condition', 'if, if-else, else if, switch'),
  (UUID_TO_BIN('70000000-0000-0000-0102-000000000005'), 'Iteration', 'for, while, do-while, nested loop, break, continue'),
  (UUID_TO_BIN('70000000-0000-0000-0102-000000000006'), 'Functions and Scope', 'Function, parameter, argument, return value, local และ global variable'),
  (UUID_TO_BIN('70000000-0000-0000-0102-000000000007'), 'Arrays', 'Array 1 มิติ, 2 มิติ, index, การเก็บข้อมูล และการวนอ่าน array'),
  (UUID_TO_BIN('70000000-0000-0000-0102-000000000008'), 'Pointers', 'Memory address, pointer, & และ *, การอ้างอิงตำแหน่งหน่วยความจำ'),
  (UUID_TO_BIN('70000000-0000-0000-0102-000000000009'), 'Strings and Pointers with Arrays', 'Character array, string, ''\\0'', string functions, pointer กับ array'),
  (UUID_TO_BIN('70000000-0000-0000-0102-000000000010'), 'Structures (struct)', 'struct, การประกาศสมาชิก, การเข้าถึงด้วย . และ array of structures'),
  (UUID_TO_BIN('70000000-0000-0000-0102-000000000011'), 'Recursion', 'Recursive function, base case, recursive case, factorial และ Fibonacci'),
  (UUID_TO_BIN('70000000-0000-0000-0102-000000000012'), 'Dynamic Memory Allocation', 'malloc(), calloc(), realloc(), free(), heap และ memory leak'),
  (UUID_TO_BIN('70000000-0000-0000-0102-000000000013'), 'File Input / Output', 'FILE, fopen(), fclose(), fprintf(), fscanf(), fgets(), fputs()'),
  (UUID_TO_BIN('70000000-0000-0000-0102-000000000014'), 'Debugger', 'Breakpoint, step into/over/out, การตรวจค่าตัวแปร และการหาข้อผิดพลาด'),
  (UUID_TO_BIN('70000000-0000-0000-0111-000000000001'), 'แนะนำ OOP, คลาสและวัตถุ', NULL),
  (UUID_TO_BIN('70000000-0000-0000-0111-000000000002'), 'ชนิดข้อมูลพื้นฐาน และการ implement คลาส', NULL),
  (UUID_TO_BIN('70000000-0000-0000-0111-000000000003'), 'ข้อความสั่งแบบทางเลือก (if/switch) และแบบซ้ำ (for/while)', NULL),
  (UUID_TO_BIN('70000000-0000-0000-0111-000000000004'), 'เมท็อดและคลาสเพิ่มเติม', NULL),
  (UUID_TO_BIN('70000000-0000-0000-0111-000000000005'), 'แปลงคลาสไดอะแกรมเป็นโค้ด, การดีบัก', NULL),
  (UUID_TO_BIN('70000000-0000-0000-0111-000000000006'), 'การออกแบบคลาสและ UML', NULL),
  (UUID_TO_BIN('70000000-0000-0000-0111-000000000007'), 'Array และ ArrayList', NULL),
  (UUID_TO_BIN('70000000-0000-0000-0111-000000000008'), 'Interface และ Polymorphism', NULL),
  (UUID_TO_BIN('70000000-0000-0000-0111-000000000009'), 'Inheritance (การสืบทอด)', NULL),
  (UUID_TO_BIN('70000000-0000-0000-0111-000000000010'), 'Exception และการอ่านเท็กซ์ไฟล์', NULL);
